module voting_optimizer(input [7:0][2:0] citizens, input [2:0] n, output reg [3:0] min_swaps, output reg win_possible); reg [3:0] p1_votes, p2_votes, p1_score, p2_score; always @(*) begin p1_votes = 0; p2_votes = 0; p1_score = 0; p2_score = 0; localparam int i; for (i=0; i<8; i++) begin if (i < n) begin reg [2:0] c = citizens[i][2:0]; if (c == 3'b001) p1_votes = p1_votes +1; else if (c == 3'b010) p2_votes = p2_votes +1; else if (c == 3'b100) begin if (p1_votes > p2_votes) p1_score = p1_score +1; else if (p2_votes > p1_votes) p2_score = p2_score +1; end end end if (p1_score > p2_score) begin min_swaps = 0; win_possible = 1; end else begin min_swaps = 15; win_possible = 0; end end endmodule